        ll.heap_id().is_none(),
        ll.fixed_page(),
{
    let tracked ll: LL;
    let p = core::ptr::null_mut::<Node>();
    let res = atomic_with_ghost!(
        &self.atomic => fetch_and(3);
        update old_v -> new_v;
        ghost g => {
            self.emp_inst.borrow().agree(self.emp.borrow(), &g.0);
            assert(g.1.is_Some());
            let tracked pair = g.1.tracked_unwrap();
            let tracked (delay_token, ghost_ll) = pair;
            ll = ghost_ll;
            assert(ll.wf());
            assert(ll.ptr() as int % 4 == 0);
            assert(old_v as int == ll.ptr() as int + delay_token.value().to_int());
            match delay_token.value() {
                DelayState::UseDelayedFree => {
                    assert(delay_token.value().to_int() == 0);
                    assert(old_v.addr() == ll.ptr().addr());
                },
                DelayState::Freeing => {
                    assert(delay_token.value().to_int() == 1);
                    assert(old_v.addr() == ll.ptr().addr() + 1) by(nonlinear_arith);
                },
                _ => {
                },
            }
            let mut data = ll.data@;
            data.len = 0;
            let tracked new_ll = LL {
                first: p,
                data: Ghost(data),
                perms: Tracked(Map::tracked_empty()),
            };
            g.1 = Some((delay_token, new_ll));
            assert(new_ll.wf());
        }
    );
    let ret_ll = LL {
        first: res.with_addr(res.addr() & !3),
        data: Ghost(ll.data@),
        perms: Tracked(ll.perms.get()),
    };
    proof {
        let masked = masked_ptr_delay_get_ptr(res, Ghost(delay_token.value()), Ghost(ll.ptr()));
        assert(masked.addr() == ll.ptr().addr());
        assert(ret_ll.wf());
        assert forall |i: nat| ret_ll.valid_node(i, #[trigger] ret_ll.next_ptr(i))
        by {
            assert(ll.valid_node(i, ll.next_ptr(i)));
        }
    }
    ret_ll
}

